MATCH (sp:SalesPerson)
WHERE EXISTS {
    MATCH (sqh:SalesPersonQuotaHistory)-[:QUOTA_FOR]->(sp)
    WHERE sqh.QuotaDate STARTS WITH '2013'
}
AND sp.SalesQuota IS NOT NULL
AND toFloat(sp.SalesQuota) <> 0
RETURN sp.BusinessEntityID AS BusinessEntityID
ORDER BY toFloat(sp.SalesLastYear) / toFloat(sp.SalesQuota) DESC
LIMIT 1;

MATCH (p:Product)
WHERE NOT EXISTS {
    MATCH (w:WorkOrder)-[:PRODUCES]->(p)
}
RETURN p.ProductID AS ProductID
